#include "KS/SRC/entity_interface_shared.h"
#include "KS/SRC/stringx.h"

typedef unsigned long uint64;

class pstring {
    uint64 pchunk[4];
};

struct sceCdlFILE {
    unsigned int lsn;
    unsigned int size;
    char name[16];
    unsigned char date[8];
};

class os_file {
public:
    enum mode_flags {
        FILE_READ = 1,
        FILE_WRITE = 2,
        FILE_MODIFY = 3,
        FILE_APPEND = 4
    };

    os_file();
    os_file(const stringx &name, int flags);
    ~os_file();

private:
    stringx name;
    int flags;
    bool opened;
    bool eof;
    bool from_cd;
    union {
        int host;
        sceCdlFILE cd;
    } io;
    int curr_fp;
} __attribute__((aligned(8)));

class stash_index_entry;

class stash {
    stash_index_entry *index;
    bool opened;
    bool eof;
    unsigned int fp;
    unsigned int max_fp;
    pstring fullname;
};

class text_file {
public:
    text_file();
    ~text_file();

private:
    os_file io;
    stash the_stash;
    int my_stash;
    char *buf;
    int bufpos;
    int bufamt;
    bool use_stash;
    int pushbackdata;
};

class chunk_file {
public:
    enum chunk_file_flags_t {
        MODE_MASK = 0x00FF,
        FILE_TEXT = 0x0100,
        FILE_BINARY = 0x0200
    };

    enum chunk_file_t {
        CFT_NONE,
        CFT_TEXT,
        CFT_BINARY
    };

    chunk_file();
    void open(const stringx &name, int flags = os_file::FILE_READ);
    void close();

private:
    chunk_file_t type;
    os_file binary;
    text_file text;
    stash the_stash;
    int my_stash;
};

template<class T>
class list {
    void *node;
};

class malloc_alloc {
};

template<class T, class Allocator = malloc_alloc>
class vector {
    T *start;
    T *finish;
    T *end_of_storage;
};

class ai_locomotion;
class ai_goal;

class ai_interface : public entity_interface {
protected:
    unsigned int flags;
    unsigned int team;
    unsigned int enemy_team;
    static list<ai_interface *> all_ai_interfaces;
    ai_locomotion *locomotion;
    vector<ai_goal *, malloc_alloc> goals;
    ai_goal *current_goal;
    entity *target;
    float help_timer;
    int disable_count;

    void read_ai_file(const stringx &file);
    void read_goal_pack(const stringx &file);
    void read_goal(chunk_file &file, const stringx &label);

public:
    virtual ~ai_interface();
    void read_data(chunk_file &file);
};

bool file_finder_exists(
    const stringx &filename,
    const stringx &extension,
    stringx *found_name = 0);
void error(const char *format, ...);

extern const char ai_extension[];
extern const char ai_not_found[];

