__asm__(".equ ai_not_found, 0x004B7CB8");

void ai_interface::read_ai_file(const stringx &file)
{
  stringx       filename;
  if ( !file_finder_exists(file, stringx(ai_extension), &filename) )
  {
    error(ai_not_found, file.c_str());
    return;
  }

  chunk_file    fs;
  fs.open( filename, os_file::FILE_READ | chunk_file::FILE_TEXT );
  read_data(fs);
  fs.close();
}
